using Godot;
using System;
using System.Linq;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class BakeEditingOperations:RefCounted
{
    private readonly PhysicsSettingsOperations _settings=new();private readonly ActorAnimationOperations _animation=new();private readonly ActorRuntimeOperations _clips=new();
    private static readonly string[] Visual={"physics","material","color","text","uniforms","shader","shadow_casting","structure_overlay","structure_assembly","destruction_overrides","destruction_setup","destruction_setup_actions","destruction_vfx_offset","destruction_interior","destruction_interior_color","destruction_preset"};private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;private static GArray DebrisVisual()=>GD.Load<GDScript>("res://scripts/actors/physics/destruction/debris_definition.gd").GetScriptConstantMap()["VISUAL"].AsGodotArray();
    public string prefix_signature(RefCounted model,double time){var rows=new GArray();var debris=DebrisVisual();foreach(var item in model.Get("actors").AsGodotArray()){var actor=item.As<Resource>();if(Get(actor.Get("values").AsGodotDictionary(),"position").VariantType!=Variant.Type.Vector3)continue;var clip=model.Call("clip_for_actor_id",actor.Get("id")).As<Resource>();double local=_clips.local_time(clip,time);var values=_animation.sampled_values(actor,local);var physical=new Settings();foreach(var entry in values){string name=entry.Key.ToString();if(actor.Get("type_id").AsString()=="fog_volume"){var fog=GD.Load<GDScript>("res://scripts/actors/fog/fog_motion_definition.gd");if(fog.Call("physical_path",new[]{name}).AsBool())physical[entry.Key]=fog.Call("content",entry.Value);continue;}if(name.StartsWith("growth_",StringComparison.Ordinal)||Visual.Contains(name)||debris.Contains(name))continue;physical[entry.Key]=name is "destruction_material" or "destruction_region" or "destruction_region_2"?GD.Load<GDScript>("res://scripts/actors/physics/destruction/destruction_material.gd").Call("physical",entry.Value):entry.Value;}var operations=new Settings();foreach(var entry in Get(values,"destruction_operations",new Settings()).AsGodotDictionary()){var operation=entry.Value.AsGodotDictionary();if(Get(operation,"enabled",true).AsBool()&&Get(operation,"time",0).AsDouble()<=local)operations[entry.Key]=operation;}physical[new StringName("destruction_operations")]=operations;var rules=Get(values,"destruction_fragments",new Settings()).AsGodotDictionary().Duplicate(true);foreach(var value in rules.Values){var rule=value.AsGodotDictionary();if(Get(rule,"impulse_time",0).AsDouble()>local){rule.Remove("impulse_time");rule.Remove("impulse");}if(Get(rule,"from",0).AsDouble()>local)foreach(string key in new[]{"from","to","target","mode","strength","damping"})rule.Remove(key);}physical[new StringName("destruction_fragments")]=rules;var config=_settings.sample(actor,local);if(config["mode"].AsInt32()==4)config["mode"]=Get(config["bake"].AsGodotDictionary(),"source_mode",1).AsInt32();config.Remove("bake");if(config["mode"].AsInt32()!=3)config.Remove("frozen");var forces=new GArray();foreach(var value in config["forces"].AsGodotArray())if(Get(value.AsGodotDictionary(),"time",0).AsDouble()<=local)forces.Add(value);config["forces"]=forces;rows.Add(new GArray{actor.Get("id"),actor.Get("parent_id"),physical,config,new GArray{clip.Get("start_time"),clip.Get("duration"),clip.Get("source_offset"),clip.Get("playback_speed")}});}return GD.VarToStr(_settings.canonical(rows)).Sha256Text();}
    public Settings group_cache(Resource actor)=>_settings.authored(actor)["bake"].AsGodotDictionary();
    public string remap_id(string id,Settings ids){var parts=id.Split(":fragment:",StringSplitOptions.None);if(parts.Length>1)return Get(ids,parts[0],parts[0]).AsString()+":fragment:"+parts[1];return Get(ids,id,id).AsString();}
    public Settings remap_frame(Settings frame,Settings ids,Transform3D offset){var result=new Settings();foreach(var entry in frame){string key=entry.Key.ToString();if(key.StartsWith('@')){result[entry.Key]=entry.Value;continue;}var state=entry.Value.AsGodotDictionary().Duplicate(true);string next=Get(ids,key,key).AsString();state["pose"]=offset*state["pose"].AsTransform3D();foreach(string field in new[]{"v","w"})if(state.ContainsKey(field))state[field]=offset.Basis*state[field].AsVector3();foreach(var value in Get(state,"destruction_fragments",new GArray()).AsGodotArray()){var fragment=value.AsGodotDictionary();var parts=fragment["id"].AsString().Split(":fragment:",StringSplitOptions.None);fragment["id"]=next+":fragment:"+(parts.Length>1?parts[1]:"");fragment["pose"]=offset*fragment["pose"].AsTransform3D();fragment["v"]=offset.Basis*fragment["v"].AsVector3();fragment["w"]=offset.Basis*fragment["w"].AsVector3();}foreach(var value in Get(state,"destruction_events",new GArray()).AsGodotArray()){var item=value.AsGodotDictionary();item["source_actor"]=next;item["point"]=offset*item["point"].AsVector3();item["normal"]=offset.Basis*item["normal"].AsVector3();item["velocity"]=offset.Basis*item["velocity"].AsVector3();}if(state.ContainsKey("structural")){var structure=state["structural"].AsGodotDictionary();structure["island"]=remap_id(Get(structure,"island","").AsString(),ids);var fragments=new Settings();foreach(var value in Get(structure,"fragments",new Settings()).AsGodotDictionary()){var info=value.Value.AsGodotDictionary();info["island"]=remap_id(Get(info,"island","").AsString(),ids);fragments[remap_id(value.Key.ToString(),ids)]=info;}structure["fragments"]=fragments;}result[next]=state;}return result;}
    public string portable_signature(Resource actor){var values=new Settings();var debris=DebrisVisual();foreach(var entry in actor.Get("values").AsGodotDictionary()){string name=entry.Key.ToString();if(Visual.Contains(name)||debris.Contains(name)||name.StartsWith("growth_",StringComparison.Ordinal))continue;values[entry.Key]=entry.Value;}var config=_settings.authored(actor);config["mode"]=Get(config["bake"].AsGodotDictionary(),"source_mode",1).AsInt32();config.Remove("bake");config.Remove("frozen");var tracks=new GArray();foreach(var value in actor.Get("animation_tracks").AsGodotArray()){var track=value.As<Resource>();var path=track.Get("path").AsStringArray();if(path.Length==0||new[]{"destruction_overrides","destruction_vfx_offset","color","material","shader","uniforms","shadow_casting"}.Contains(path[0]))continue;var keys=new GArray();foreach(var item in track.Get("keys").AsGodotArray()){var key=item.As<Resource>();keys.Add(new GArray{key.Get("time"),key.Get("value"),key.Get("interpolation"),key.Get("attenuation"),key.Get("value_curve")});}tracks.Add(new GArray{path,keys});}return GD.VarToStr(_settings.canonical(new GArray{values,config,tracks})).Sha256Text();}
    public Settings portable_scene(Control editor){var scene=editor.Call("capture_scene_data").As<Resource>();int caches=0;double start=double.NegativeInfinity,end=double.PositiveInfinity;foreach(var item in scene.Get("actors").AsGodotArray()){var actor=item.As<Resource>();if(!_settings.configured(actor))continue;var config=_settings.authored(actor);var bake=config["bake"].AsGodotDictionary();if(config["type"].AsInt32() is not (0 or 2))return new Settings{["error"]="Reusable baked assemblies currently support rigid bodies and real destruction fragments. Other solvers must be recalculated after instantiation."};if(config["mode"].AsInt32()!=4||!ActorDataOperations.ScriptIs(Get(bake,"cache").AsGodotObject() as Resource,"res://scripts/actors/physics/destruction/physics_bake_cache.gd")||Get(bake,"signature","").AsString()!=editor.Get("physics").AsGodotObject().Get("signature").AsString())return new Settings{["error"]="Bake the complete interacting group before capturing a reusable assembly."};Resource? clip=null;foreach(var value in scene.Get("clips").AsGodotArray())if(value.As<Resource>().Get("actor_id").AsString()==actor.Get("id").AsString()){clip=value.As<Resource>();break;}if(clip==null)return new Settings{["error"]="The assembly has an actor without timing data."};bake["portable"]=true;bake["source_actor"]=actor.Get("id");bake["owner"]=actor.Get("id");bake["source_start"]=clip.Get("start_time");bake["source_speed"]=clip.Get("playback_speed");bake["source_offset"]=clip.Get("source_offset");bake["portable_authored"]=portable_signature(actor);config["bake"]=bake;actor.Get("values").AsGodotDictionary()[new StringName("physics")]=config;caches++;start=Math.Max(start,bake["from"].AsDouble());end=Math.Min(end,bake["to"].AsDouble());}if(caches==0)return new Settings{["error"]="The scene has no baked rigid/destruction group."};if(end<=start)return new Settings{["error"]="Baked groups must share a nonempty playback interval."};foreach(var item in scene.Get("clips").AsGodotArray()){var clip=item.As<Resource>();double oldStart=clip.Get("start_time").AsDouble(),first=Math.Max(start,oldStart),last=Math.Min(end,oldStart+clip.Get("duration").AsDouble());clip.Set("source_offset",clip.Get("source_offset").AsDouble()+(first-oldStart)*clip.Get("playback_speed").AsDouble());clip.Set("start_time",Math.Clamp(first,start,end));clip.Set("duration",Math.Max(0,last-first));}return new Settings{["error"]="",["scene"]=scene};}
    public double portable_time(Settings bake,Resource clip,double time)=>Get(bake,"source_start",0).AsDouble()+(_clips.local_time(clip,time)-Get(bake,"source_offset",0).AsDouble())/Math.Max(.001,Get(bake,"source_speed",1).AsDouble());
    public double current_time(Settings bake,Resource clip,double time)=>clip.Get("start_time").AsDouble()+((time-Get(bake,"source_start",0).AsDouble())*Get(bake,"source_speed",1).AsDouble()+Get(bake,"source_offset",0).AsDouble()-clip.Get("source_offset").AsDouble())/Math.Max(.001,clip.Get("playback_speed").AsDouble());
    public Settings portable_state(Settings state,Settings bake,Resource clip,Transform3D offset){var ids=Get(bake,"portable_ids",new Settings()).AsGodotDictionary();var mapped=remap_frame(new Settings{[bake["source_actor"].AsString()]=state},ids,offset);var result=Get(mapped,bake["owner"].AsString(),new Settings()).AsGodotDictionary();if(result.Count==0)return result;double speed=clip.Get("playback_speed").AsDouble()/Math.Max(.001,Get(bake,"source_speed",1).AsDouble());if(result.ContainsKey("initial_time"))result["initial_time"]=current_time(bake,clip,result["initial_time"].AsDouble());if(result.ContainsKey("initial_pose"))result["initial_pose"]=offset*result["initial_pose"].AsTransform3D();foreach(string field in new[]{"v","w"})if(result.ContainsKey(field))result[field]=result[field].AsVector3()*(float)speed;foreach(var value in Get(result,"destruction_fragments",new GArray()).AsGodotArray()){var fragment=value.AsGodotDictionary();fragment["v"]=fragment["v"].AsVector3()*(float)speed;fragment["w"]=fragment["w"].AsVector3()*(float)speed;}foreach(var value in Get(result,"destruction_events",new GArray()).AsGodotArray()){var item=value.AsGodotDictionary();foreach(string field in new[]{"time","scene_time","birth_time"})if(item.ContainsKey(field))item[field]=current_time(bake,clip,item[field].AsDouble());item["age_scale"]=speed;}return result;}
}
